#include <bits/stdc++.h>
using namespace std;

template <typename T>
T egcd(T a, T b, T& x, T& y) {
  if (b == 0) { x = 1; y = 0; return a; }
  T x1, y1;
  T g = egcd(b, a % b, x1, y1);
  x = y1;
  y = x1 - (a / b) * y1;
  return g;
}

template <typename T>
T modInv(T a, T m) {
  T x, y;
  T g = egcd(a, m, x, y);
  assert(g == 1);
  if (x < 0) x += m;
  return x;
}

template <typename T>
class Modular {
 public:
  using Type = typename decay<decltype(T::value)>::type;

  constexpr Modular() : value() {}
  template <typename U>
  Modular(const U& x) { value = normalize(x); }

  template <typename U>
  static Type normalize(const U& x) {
    Type v = static_cast<Type>(x % mod());
    if (v < 0) v += mod();
    return v;
  }

  const Type& operator()() const { return value; }
  template <typename U>
  explicit operator U() const { return static_cast<U>(value); }
  constexpr static Type mod() { return T::value; }

  Modular& operator+=(const Modular& other) { if ((value += other.value) >= mod()) value -= mod(); return *this; }
  Modular& operator-=(const Modular& other) { if ((value -= other.value) < 0) value += mod(); return *this; }
  template <typename U> Modular& operator+=(const U& other) { return *this += Modular(other); }
  template <typename U> Modular& operator-=(const U& other) { return *this -= Modular(other); }
  Modular& operator++() { return *this += 1; }
  Modular& operator--() { return *this -= 1; }
  Modular operator++(int) { Modular result(*this); *this += 1; return result; }
  Modular operator--(int) { Modular result(*this); *this -= 1; return result; }
  Modular operator-() const { return Modular(-value); }

  template <typename U = T>
  typename enable_if<is_same<typename Modular<U>::Type, int>::value, Modular>::type& operator*=(const Modular& rhs) {
    value = normalize(static_cast<int64_t>(value) * static_cast<int64_t>(rhs.value));
    return *this;
  }
  template <typename U = T>
  typename enable_if<is_same<typename Modular<U>::Type, int64_t>::value, Modular>::type& operator*=(const Modular& rhs) {
    int64_t q = static_cast<int64_t>(static_cast<long double>(value) * rhs.value / mod());
    value = normalize(value * rhs.value - q * mod());
    return *this;
  }
  template <typename U = T>
  typename enable_if<!is_integral<typename Modular<U>::Type>::value, Modular>::type& operator*=(const Modular& rhs) {
    value = normalize(value * rhs.value);
    return *this;
  }

  Modular& operator/=(const Modular& other) { return *this *= Modular(modInv(other.value, mod())); }

  template <typename U>
  friend bool operator==(const Modular<U>& lhs, const Modular<U>& rhs);
  template <typename U>
  friend bool operator<(const Modular<U>& lhs, const Modular<U>& rhs);
  template <typename U>
  friend std::istream& operator>>(std::istream& stream, Modular<U>& number);

 private:
  Type value;
};

template <typename T> bool operator==(const Modular<T>& lhs, const Modular<T>& rhs) { return lhs.value == rhs.value; }
template <typename T, typename U> bool operator==(const Modular<T>& lhs, U rhs) { return lhs == Modular<T>(rhs); }
template <typename T, typename U> bool operator==(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) == rhs; }

template <typename T> bool operator!=(const Modular<T>& lhs, const Modular<T>& rhs) { return !(lhs == rhs); }
template <typename T, typename U> bool operator!=(const Modular<T>& lhs, U rhs) { return !(lhs == rhs); }
template <typename T, typename U> bool operator!=(U lhs, const Modular<T>& rhs) { return !(lhs == rhs); }

template <typename T> bool operator<(const Modular<T>& lhs, const Modular<T>& rhs) { return lhs.value < rhs.value; }

template <typename T> Modular<T> operator+(const Modular<T>& lhs, const Modular<T>& rhs) { return Modular<T>(lhs) += rhs; }
template <typename T, typename U> Modular<T> operator+(const Modular<T>& lhs, U rhs) { return Modular<T>(lhs) += rhs; }
template <typename T, typename U> Modular<T> operator+(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) += rhs; }

template <typename T> Modular<T> operator-(const Modular<T>& lhs, const Modular<T>& rhs) { return Modular<T>(lhs) -= rhs; }
template <typename T, typename U> Modular<T> operator-(const Modular<T>& lhs, U rhs) { return Modular<T>(lhs) -= rhs; }
template <typename T, typename U> Modular<T> operator-(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) -= rhs; }

template <typename T> Modular<T> operator*(const Modular<T>& lhs, const Modular<T>& rhs) { return Modular<T>(lhs) *= rhs; }
template <typename T, typename U> Modular<T> operator*(const Modular<T>& lhs, U rhs) { return Modular<T>(lhs) *= rhs; }
template <typename T, typename U> Modular<T> operator*(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) *= rhs; }

template <typename T> Modular<T> operator/(const Modular<T>& lhs, const Modular<T>& rhs) { return Modular<T>(lhs) /= rhs; }
template <typename T, typename U> Modular<T> operator/(const Modular<T>& lhs, U rhs) { return Modular<T>(lhs) /= rhs; }
template <typename T, typename U> Modular<T> operator/(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) /= rhs; }

template<typename T, typename U>
Modular<T> power(const Modular<T>& a, const U& b) {
  assert(b >= 0);
  Modular<T> x = a, res = 1;
  U p = b;
  while (p > 0) {
    if (p & 1) res *= x;
    x *= x;
    p >>= 1;
  }
  return res;
}

template <typename T>
std::ostream& operator<<(std::ostream& stream, const Modular<T>& number) {
  return stream << number();
}

template <typename T>
std::istream& operator>>(std::istream& stream, Modular<T>& number) {
  typename common_type<typename Modular<T>::Type, int64_t>::type x;
  stream >> x;
  number.value = Modular<T>::normalize(x);
  return stream;
}

using ModType = int;
struct VarMod { static ModType value; };
ModType VarMod::value;
ModType& md = VarMod::value;
using Mint = Modular<VarMod>;

int n, m;

int main() {
  cin >> n >> m >> md;
  vector<Mint> fact = {1};
  vector<Mint> inv_fact = {1};
  auto C = [&](int x, int y) {
    int sz = max(x, y);
    while((int) fact.size() < sz + 1) {
      fact.push_back(fact.back() * fact.size());
      inv_fact.push_back(1 / fact.back());
    }
    if(y < 0 || y > x) return Mint(0);
    return fact[x] * inv_fact[y] * inv_fact[x - y];
  };
  vector<Mint> ptr_dp(m + 1);
  vector<Mint> ptr_ways(m + 1);
  ptr_ways[0] = 1;
  for(int i = 1; i <= m; i++) {
    for(int j = 0; j < i; j++) {
      int l = j, r = i - 1 - l;
      ptr_ways[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * (l + r + 2);
    }
    for(int j = 0; j < i; j++) {
      int l = j, r = i - 1 - l;
      Mint add = (Mint(l) * (l + 1) + Mint(r) * (r + 1)) / 2;
      ptr_dp[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * add;
      ptr_dp[i] += (ptr_dp[l] * ptr_ways[r] + ptr_dp[r] * ptr_ways[l]) * C(l + r, r) * (l + r + 2);
    }
  }
  vector<vector<Mint>> dp(n + 1, vector<Mint>(m + 1));
  vector<vector<Mint>> ways(n + 1, vector<Mint>(m + 1));
  ways[0][0] = 1;
  for(int i = 1; i <= n; i++) {
    for(int s = 0; s <= min(m, i); s++) {
      if(s == i) {
        dp[i][s] = ptr_dp[s];
        ways[i][s] = ptr_ways[s];
        continue;
      }
      for(int d = 1; d <= s + 1; d++) {
        Mint ft = dp[i - d][s + 1 - d];
        Mint way = ways[i - d][s + 1 - d];
        int add = d - 1;
        ways[i][s] += way * ptr_ways[add] * C(s, add);
        dp[i][s] += (way * ptr_dp[add] + ptr_ways[add] * ft) * C(s, add);
      }
    }
  }
  cout << dp[n][m];
  return 0;
}
